BEGIN READ ONLY; SET LOCAL statement_timeout='10s'; SELECT json_build_object('backends',COALESCE((SELECT json_agg(json_build_object('pid',pid,'address',host(client_addr),'port',client_port) ORDER BY pid) FROM pg_stat_activity WHERE datname=current_database() AND backend_type='client backend' AND pid<>pg_backend_pid()),'[]'::json),'advisoryLocks',(SELECT count(*) FROM pg_locks WHERE locktype='advisory' AND database=(SELECT oid FROM pg_database WHERE datname=current_database()))); ROLLBACK;
